            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_9,GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_10,GPIO_PIN_RESET);break;
        case GEAR_N:
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_9,GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_10,GPIO_PIN_SET);break;
        case GEAR_D:
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_9,GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_10,GPIO_PIN_RESET);break;
    }
}
void Gear_Shift(void)
{
    gear++;
    if(gear>GEAR_D) gear=GEAR_P;
    LED_Update(gear);
}
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin)
{
    if(GPIO_Pin == KEY0_Pin)
    {
        uint32_t now=DWT_GetCycle();
        if((now-last_tick)>DEBOUNCE_CYCLES)
        {
            last_tick=now;
            Gear_Shift();
        }
    }
}
int main(void)
{
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    DWT_Init();
    LED_Update(gear);
    while(1){}
}

汽车微处理器原理与应用
实　验　报　告
基本信息
一、团队信息与分工（5分）
1.1 团队成员基本信息
1.2 个人分工说明
刘潇霞：
我在本次汽车档位模拟器实验中承担实验主体工作。实验实操阶段，使用STM32CubeMX完成芯片引脚与外设初始化配置，负责外部中断驱动、DWT精准消抖、PRND档位状态机程序编写，在MDK-ARM中完成工程编译、排错调试，熟练使用ATK-XISP工具通过ISP模式完成固件烧录，排查解决程序档位错乱、烧录连接失败等关键问题，率先调试出档位切换的完整实验现象。实验收尾时，和组员一同商讨实验报告的大纲、各部分写作要点，梳理实验原理、故障分析等核心内容。
王舒乐：
本次实验我主要配合组长完成辅助工作。实操过程中负责实验硬件搭建，完成STM32最小系统、档位按键以及CH340、ISP烧录工具的线路接线，实操碰到接线、程序相关疑问及时向组长咨询，配合组长开展软硬件联合调试。实验结束后，我与组长共同讨论敲定实验报告全部内容与写作思路，在确定报告框架后，由我整合全部实验资料，完成报告全文的内容整理、文字撰写与格式排版工作。
1.3 团队协作过程记录
本次实验小组共两人，围绕汽车档位模拟器设计开展分工协作。实验前期，组长统筹整体实验方案，承担实验主体核心工作，负责STM32CubeMX工程配置、外部中断程序编写、DWT按键消抖等关键内容，把控整体实验进度与技术难点。组员承接硬件接线、器件摆放、线路核查等辅助工作；实操过程中遇到不懂的软硬件问题，及时交流沟通，相互配合开展硬件核验、功能测试等配套工作，协助组长推进实验落地，实现档位模拟器正常运行。
实验全部实操结束后，共同研讨实验报告的整体结构、各章节撰写要点、实验数据与故障分析内容，逐项确定报告需要收录的实验原理、操作步骤、实验现象等素材。在统一报告撰写思路之后，由组员汇总所有商讨内容与实验原始资料，完成实验报告全文的内容梳理、文字整理与格式排版工作，完成报告初稿，之后双方互相检查修改，完善最终实验报告。
二、实验目的与原理（10分）
2.1 实验目的
掌握STM32F407 GPIO外部中断的配置方法；
理解中断服务程序的设计与实现；
学习使用DWT计数器实现精准按键消抖；
掌握状态机思想在嵌入式系统中的应用；
培养硬件与软件结合的调试能力。
2.2实验原理
按键按下产生下降沿触发EXTI中断；
CPU响应中断，执行档位切换函数；
LED根据档位状态显示不同组合。
2.3 汽车电子应用场景
方向盘多功能按键控制；
换挡拨片信号检测；
车载中控物理按键响应。
三、硬件设计与连接（15分）
3.1 硬件连接图
如图 1所示：
图 1硬件连接图
3.2 引脚配置说明
说明:
1.为什么KEY0（PE4）配置为下降沿触发？
KEY0按键一端接GND，另一端接PE4，并且PE4配置了内部上拉电阻。  
未按键时：PE4保持高电平。  
按下时：PE4瞬间被拉低，会产生一个“由高到低”的跳变，即下降沿。  
下降沿触发能够“精准捕获按键按下的瞬间”，响应及时；如果使用上升沿触发，那么对应按键就会释放，这样会有延迟感。同时配合内部上拉电阻，不需要外部电路，这样硬件会简单可靠。
2. 为什么LED0（PF9）和LED1（PF10）配置为推挽输出模式？
在推挽输出模式下，GPIO引脚可以主动输出高电平或低电平，具有较强的驱动能力，完全可以直接驱动LED灯点亮或熄灭。与开漏输出相比，推挽输出不需要外接上拉电阻，电路就会更加简洁，输出电平切换速度会更快，更适合控制LED这类需要快速响应的数字输出设备。所以，我们的实验把LED控制引脚配置为推挽输出模式。
3.3 ISP烧录电路说明
BOOT0 = 1，BOOT1 = 0 进入系统存储器（ISP模式）;
通过USART1（PA9/PA10）接收烧录数据;
烧录完成后BOOT0=0，从Flash启动。
四、软件设计与实现（30分）
4.1 核心代码流程图
如图 2所示：
图 2核心代码流程图
4.2 关键代码片段及注释
档位切换函数
void Gear_Shift(void) {
    gear_position++;
    if (gear_position > 2) gear_position = 0;
    if (gear_position != last_gear) {
        last_gear = gear_position;
        LED_Update();  // 更新LED状态
    }
}
LED更新函数
static void LED_Update(GearState state)
{
 switch(state)
 {
 case GEAR_P: // 驻车档
// LED0 熄灭 (PF9 输出高电平)
 HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
 // LED1 点亮 (PF10 输出低电平)
 HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
 break;
case GEAR_R: // 倒车档
// LED0 点亮 (PF9 输出低电平)
 HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
// LED1 熄灭 (PF10 输出高电平)
 HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
 break;
 case GEAR_N: // 空档
// LED0 点亮 (PF9 输出低电平)
 HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
// LED1 点亮 (PF10 输出低电平)
 HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
 break;
 case GEAR_D: // 前进档
// LED0 熄灭 (PF9 输出高电平)
 HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
// LED1 熄灭 (PF10 输出高电平)
 HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
 break;
 }
}
补充说明：
低电平有效：我们实验的电路中LED阳极接3.3V，阴极接GPIO，所以GPIO输出低电平时LED点亮，输出高电平时LED熄灭。
档位与LED的对应关系：
P档：LED1点亮（常作为驻车指示灯），LED0熄灭。
R档：LED0点亮（倒车灯），LED1熄灭。
N档：两个LED同时点亮（提示空档状态）。
D档：两个LED同时熄灭（前进档正常行驶）。
中断回调函数
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin) {
    if(GPIO_Pin == KEY0_Pin) {
        HAL_Delay(50);  // 软件消抖
        if(HAL_GPIO_ReadPin(KEY0_GPIO_Port, KEY0_Pin) == GPIO_PIN_RESET) {
            Gear_Shift();
        }
    }
}
4.3中断服务程序说明
配置为下降沿触发，按键按下瞬间触发中断；
在回调函数中加入消抖逻辑，防止一次按下多次触发；
中断优先级可根据需要调整。
说明：
1.DWT消抖原理说明 
DWT是ARM Cortex-M内核内置的一个调试组件，其中的CYCCNT寄存器是一个32位自由运行的周期计数器，每个时钟周期加1。通过使能DWT计数器，可以在中断服务函数中读取当前计数值，与上次触发时的计数值相减，计算出两次中断的时间间隔（以时钟周期为单位）。若时间间隔小于设定的消抖阈值（如50ms×系统时钟频率），则判定为按键抖动，直接忽略本次中断；否则确认为有效按键。  
相比传统的HAL_Delay阻塞延时，DWT消抖不占用CPU等待时间，在延迟期间CPU仍可处理其他任务，实时性更高，且精度可达1个时钟周期。
2.EXTI中断优先级配置
在STM32CubeMX的NVIC（Nested Vectored Interrupt Controller）设置中，将EXTI4中断的抢占优先级（Preemption Priority）配置为2，子优先级（Sub Priority）配置为0。抢占优先级决定了中断能否打断其他中断，数值越小优先级越高。
3.系统时钟与GPIO时钟配置
本实验使用STM32CubeMX配置系统时钟如下：  
时钟源：外部高速晶振（HSE），频率8MHz；
PLL倍频：HSE 8MHz / 2（分频）× 336（倍频）/ 2（分频） = 168MHz；  
系统时钟频率：168MHz。  
