档位切换函数
void Gear_Shift(void) {
    // 档位加1，实现升档效果
    gear_position++;
    // 如果档位超过最大值2（即档位3），则回到0（空档），形成循环
    // 假设只有0、1、2三个档位
    if (gear_position > 2) {
        gear_position = 0;
    }
    // 判断档位是否真的发生了变化（防止重复调用时无意义刷新）
    if (gear_position != last_gear) {
        // 更新上一次档位记录，供下次比较使用
        last_gear = gear_position;
        // 调用LED更新函数，根据新档位点亮对应的LED
        LED_Update();
    }
}
LED调动函数
void LED_Update(void) {
    // 根据档位值进行分支选择
    switch(gear_position) {
        case 0:  // 空档
            // 熄灭LED0：输出低电平（假设高电平点亮，则低电平熄灭）
            // 注意：实际参数应为 HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_RESET)
            HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_RESET);
            // 熄灭LED1
            HAL_GPIO_WritePin(LED1_GPIO_Port, LED1_Pin, GPIO_PIN_RESET);
            break;
        case 1:  // 1档
            // 点亮LED0：输出高电平
            HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_SET);
            // 熄灭LED1
            HAL_GPIO_WritePin(LED1_GPIO_Port, LED1_Pin, GPIO_PIN_RESET);
            break;
        case 2:  // 2档
            // 熄灭LED0
            HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_RESET);
            // 点亮LED1
            HAL_GPIO_WritePin(LED1_GPIO_Port, LED1_Pin, GPIO_PIN_SET);
            break;
    }
}
中断回调函数
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin) {
    // 判断触发中断的引脚是不是KEY0所在的引脚
    if(GPIO_Pin == KEY0_Pin) {
        // 软件消抖：延时50毫秒，跳过按键抖动的不稳定期
        // 注意：HAL_Delay 使用SysTick中断，在中断回调中调用会阻塞其他中断，
        // 但对于简单实验可以接受。高标准应用建议使用非阻塞消抖。
        HAL_Delay(50);
        // 延时后再次读取KEY0的电平，确认是否真的按下（低电平有效）
        // 如果还是低电平，说明是有效按键，而非抖动
        if(HAL_GPIO_ReadPin(KEY0_GPIO_Port, KEY0_Pin) == GPIO_PIN_RESET) {
            // 调用档位切换函数，改变gear_position并更新LED
            Gear_Shift();
        }
        // 可选：清除中断标志（HAL库已自动清除，通常不需要手动操作）
        // __HAL_GPIO_EXTI_CLEAR_IT(GPIO_Pin);
    }
}

