// 
#include "stm32f4xx_hal.h"
// 定义四个档位
typedef enum {
	GEAR_P,	// 停车档
	GEAR_R,	// 倒车档
	GEAR_N,	// 空挡
	GEAR_D	// 前进档
} Gear_t;
Gear_t currentGear = GEAR_P;	// 开机默认P档
#define DEBOUNCE_TIME 50		// 防抖时间50毫秒
uint32_t last_key_time = 0;	// 记录上一次按键时间
// 初始化DWT计时功能
void DWT_Init(void)
{
	CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
	DWT->CYCCNT = 0;
	DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;
}
// 获取当前计时（毫秒）
uint32_t DWT_GetTime(void)
{
	return DWT->CYCCNT / (HAL_RCC_GetHCLKFreq() / 1000);
}
// 根据档位更新LED灯状态
void LED_Update(void)
{
	switch(currentGear)
	{
		case GEAR_P:
			HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
			HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
			break;
		case GEAR_R:
			HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
			HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
			break;
		case GEAR_N:
			HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
			HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
			break;
		case GEAR_D:
			HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
			HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
			break;
		default: break;
	}
}
// 档位切换函数
void Gear_Shift(void)
{
	currentGear++;
	if(currentGear > GEAR_D)
	{
		currentGear = GEAR_P; // 循环回到P档
	}
	LED_Update();
