B.LED显示更新商数
功能：根据当前档位控制LED，LED低电平点亮、高电平熄灭
PF9、PF10 配置为推挽输出模式
static void LED_Update(GearState state)
switch(state)
{
case GEAR_P:  //P挡：PF9亮，PF10灭
HAL_GPIO_WritePin(GPIOF,GPIO_PIN_9,GPIO_PIN_SET)
HAL_GPIO_WritePin(GPIOF,GPIO_PIN_10,GPIO_PIN_RESET);
Break;
case GEAR_R:  //R档：PF9灭，PF10亮
HAL_GPIO_WritePin(GPIOF,GPIO_PIN_9,GPIO_PIN_RESET);
HAL_GPIO_WritePin(GPIOF,GPIO_PIN_10,GPIO_PIN_SET);
break;
case GEAR N:  // N档：双灯全灭
HAL_GPIO_WritePin(GPIOF,GPIO_PIN_9.GPI0_PIN_RESET);
HAL_GPIO_WritePin(GPIOF,GPIO_PIN_10,GPIO_PIN_RESET);
Break;
case GEAR D:  //D档：双灯全亮
HAL_GPIO_WritePin(GPIOF,GPIO_PIN_9,GPIO_PIN_SET);
HAL_GPIO_WritePin（GPIOF,GPIO_PIN_10,GPIO_PIN_SET)；
break;
void Gear_Shift(void)
{
    gear = (gear + 1) % 4;
    LED_Update(gear);  // 切换档位后刷新LED状态
}
