/* USER CODE BEGIN 0 */
// DWT 初始化函数（用于精准消抖）
void DWT_Init(void)
{
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk; // 启用 DWT 追踪
    DWT->CYCCNT = 0;                                // 清零计数器
    DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;            // 启用 CYCCNT 计数
}
// 读取 DWT 计数器值
uint32_t DWT_GetCycle(void)
{
    return DWT->CYCCNT;
}
// LED 状态更新函数 (根据实验要求映射)
void LED_Update(GearState state)
{
    switch(state)
    {
        case GEAR_P: // P档 (LED0亮，LED1灭)
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            break;
        case GEAR_R: // R档 (LED0灭，LED1亮)
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
            break;
        case GEAR_N: // N档 (LED0灭，LED1灭)
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            break;
        case GEAR_D: // D档 (LED0亮，LED1亮)
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
            break;
    }
}
// 档位切换逻辑：P -> R -> N -> D -> P 循环
void Gear_Shift(void)
{
    gear = (gear + 1) % 4; // 利用枚举顺序循环
}
