/* 1. 档位枚举类型定义 */
typedef enum {
    GEAR_P = 0,  // 停车档
    GEAR_R,    
  // 倒车档
    GEAR_N,      // 空档
    GEAR_D       // 前进档
} GearState;
volatile GearState currentGear = GEAR_P; // 当前档位状态，volatile防止被编译器优化
/* 2. DWT延时初始化与延时函数 */
static void DWT_Init(void) {
    // 使能DWT跟踪单元：设置DEMCR寄存器的第24位为1
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
    // 复位DWT计数器
    DWT->CYCCNT = 0;
    // 使能DWT计数器：设置DWT_CTRL寄存器的第0位为1
    DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;
}
static uint32_t DWT_GetTick(void) {
    return DWT->CYCCNT; // 获取当前CPU周期计数值
}
// 计算从start时间点开始，是否已经过去了us微秒（此版本未直接使用，逻辑在中断中）
// 实际中断中通过差值判断是否超过50ms (8400000 cycles)
/* 3. LED显示更新函数 */
static void LED_Update(GearState state) {
    switch(state) {
        case GEAR_P: // 停车档：LED0亮，LED1灭
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET); // 点亮LED0
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);  // 熄灭LED1
            break;
        case GEAR_R: // 倒车档：LED0灭，LED1亮
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            break;
        case GEAR_N: // 空档：两灯全灭
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
            break;
        case GEAR_D: // 前进档：两灯全亮
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            break;
4.3 中断服务程序说明
配置方法：在STM32CubeMX中，将PE4引脚配置为GPIO_EXTI4，然后在NVIC（Nested Vectored Interrupt Controller）设置中，使能EXTI line4 interrupt，并设置其抢占优先级为0，响应优先级为0（最高）。STM32CubeMX会自动生成中断初始化代码和EXTI4_IRQHandler函数框架。
·触发条件： 当PE4引脚上检测到一个下降沿（电平从高到低的跳变）时，EXTI4中断线被挂起，如果NVIC中该中断已使能，CPU将立即响应，并跳转到EXTI4_IRQHandler。
·处理逻辑： 用户在stm32f4xx_it.c文件中的HAL_GPIO_EXTI_Callback回调函数中编写具体逻辑。本实验的处理逻辑如下：
1.首先调用DWT_GetTick()获取当前时间戳。
2.与上一次保存的时间戳lastTick做差，判断差值是否大于DEBOUNCE_TIME_CYCLES（对应50ms）。
3.如果满足条件，判定为有效按键，更新lastTick为当前时间戳，并执行档位切换：currentGear = (currentGear + 1) % 4。
4.调用LED_Update(currentGear)，根据新档位刷新LED状态。
5.函数末尾，清除HAL库中EXTI的中断挂起标志位（HAL_GPIO_EXTI_Callback会自动清除硬件标志，无需手动操作）。
