// 1. 档位枚举定义（建议写在头文件或代码开头）
typedef enum {
    GEAR_P = 0,
    GEAR_R,
    GEAR_N,
    GEAR_D,
    GEAR_MAX
} GearState;
volatile GearState gear = GEAR_P; // 上电默认P档
// 2. DWT消抖配置
uint32_t Last_DWT_Cnt = 0;
#define DWT_50MS 8400000UL // 168M主频50ms对应计数
// 3. LED状态更新函数（修正引脚对应，低电平点亮）
static void LED_Update(GearState state) {
    switch(state) {
        case GEAR_P: // P档：LED0亮，LED1灭（低电平点亮）
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET); // LED0亮
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);    // LED1灭
            break;
        case GEAR_R: // R档：LED0灭，LED1亮
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);    // LED0灭
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);   // LED1亮
            break;
        case GEAR_N: // N档：两灯全灭
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            break;
        case GEAR_D: // D档：两灯全亮
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
            break;
        default:
            // 默认回到P档
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            break;
    }
}
// 4. 档位切换函数（按P→R→N→D→P顺序循环）
void Gear_Shift(void) {
    switch(gear) {
        case GEAR_P:
            gear = GEAR_R;
            break;
        case GEAR_R:
            gear = GEAR_N;
            break;
        case GEAR_N:
            gear = GEAR_D;
            break;
        case GEAR_D:
            gear = GEAR_P;
            break;
        default:
            gear = GEAR_P;
            break;
    }
    // 切换后更新LED显示
    LED_Update(gear);
}
// 5. 外部中断回调函数（按键消抖+换挡）
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin) {
    uint32_t Current_DWT_Cnt = DWT->CYCCNT;
    if(GPIO_Pin == GPIO_PIN_4) { // PE4按键触发中断
        // DWT消抖：间隔≥50ms才执行
        if((Current_DWT_Cnt - Last_DWT_Cnt) >= DWT_50MS) {
            Last_DWT_Cnt = Current_DWT_Cnt;
            Gear_Shift(); // 执行档位切换
        }
    }
}
// 6. 初始化配置（补充GPIO模式说明，写在报告里）
void MX_GPIO_Init(void) {
    GPIO_InitTypeDef GPIO_InitStruct = {0};
    // 按键PE4初始化：外部中断下降沿触发
    __HAL_RCC_GPIOE_CLK_ENABLE();
    GPIO_InitStruct.Pin = GPIO_PIN_4;
    GPIO_InitStruct.Mode = GPIO_MODE_IT_FALLING; // 下降沿触发中断
    GPIO_InitStruct.Pull = GPIO_NOPULL;
    HAL_GPIO_Init(GPIOE, &GPIO_InitStruct);
    HAL_NVIC_SetPriority(EXTI4_IRQn, 2, 0);
    HAL_NVIC_EnableIRQ(EXTI4_IRQn);
    // LED PF9/PF10初始化：推挽输出
    __HAL_RCC_GPIOF_CLK_ENABLE();
    GPIO_InitStruct.Pin = GPIO_PIN_9 | GPIO_PIN_10;
    GPIO_InitStruct.Mode = GPIO_MODE_OUTPUT_PP; // 推挽输出模式
    GPIO_InitStruct.Pull = GPIO_NOPULL;
    GPIO_InitStruct.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(GPIOF, &GPIO_InitStruct);
    // 上电默认P档灯效
    LED_Update(GEAR_P);
