1. 档位枚举定义（建议写在头文件或代码开头）
typedef enum {
    GEAR_P = 0,
    GEAR_R,
    GEAR_N,
    GEAR_D,
    GEAR_MAX
} GearState;
volatile GearState gear = GEAR_P; // 上电默认P档
 2. DWT消抖配置
uint32_t Last_DWT_Cnt = 0;
#define DWT_50MS 8400000UL // 168M主频50ms对应计数
// DWT初始化函数（需在main函数开头调用）
void DWT_Init(void)
{
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;  // 使能DWT外设
    DWT->CYCCNT = 0;                                  // 清零DWT计数器
    DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;              // 使能周期计数器
}
// 按键消抖逻辑（在中断回调里使用）
#define DWT_50MS 8400000UL  // 168MHz下50ms对应的计数周期
uint32_t Last_DWT_Cnt = 0;
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin)
{
    uint32_t Current_DWT_Cnt = DWT->CYCCNT; // 读取当前DWT计数值
    if(GPIO_Pin == GPIO_PIN_4)
    {
        // 消抖判断：两次按键间隔≥50ms才有效
        if((Current_DWT_Cnt - Last_DWT_Cnt) >= DWT_50MS)
        {
            Last_DWT_Cnt = Current_DWT_Cnt;
            Gear_Shift(); // 执行档位切换
        }
    }
}
3. LED状态更新函数（修正引脚对应，低电平点亮）
static void LED_Update(GearState state) {
    switch(state) {
        case GEAR_P: // P档：LED0亮，LED1灭（低电平点亮）
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET); // LED0亮
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);    // LED1灭
            break;
        case GEAR_R: // R档：LED0灭，LED1亮
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);    // LED0灭
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);   // LED1亮
            break;
        case GEAR_N: // N档：两灯全灭
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            break;
        case GEAR_D: // D档：两灯全亮
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
            break;
        default:
            // 默认回到P档
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            break;
    }
}
 4. 档位切换函数（按P→R→N→D→P顺序循环）
void Gear_Shift(void) {
    switch(gear) {
        case GEAR_P:
            gear = GEAR_R;
            break;
        case GEAR_R:
            gear = GEAR_N;
            break;
        case GEAR_N:
            gear = GEAR_D;
            break;
        case GEAR_D:
            gear = GEAR_P;
            break;
        default:
            gear = GEAR_P;
            break;
    }
    // 切换后更新LED显示
    LED_Update(gear);
}
5. 外部中断回调函数（按键消抖+换挡）
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin) {
    uint32_t Current_DWT_Cnt = DWT->CYCCNT;
    if(GPIO_Pin == GPIO_PIN_4) { // PE4按键触发中断
        // DWT消抖：间隔≥50ms才执行
        if((Current_DWT_Cnt - Last_DWT_Cnt) >= DWT_50MS) {
            Last_DWT_Cnt = Current_DWT_Cnt;
            Gear_Shift(); // 执行档位切换
        }
    }
}
